import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyCuDan = () => {
    // State lưu phòng đang được chọn
    const [selectedRoom, setSelectedRoom] = useState(null);

    // GIẢ ĐỊNH: Sau này bạn sẽ fetch dữ liệu từ database và lưu vào đây
    // Hiện tại mình để trống hoặc chỉ có vài mẫu để test giao diện
    const databaseResidents = {
        // Ví dụ một phòng đã có người
        "101": { name: "Nguyễn Phan Vinh", gender: "Nam", phone: "09xxx", members: 1, parking: "A-01" },
    };

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // Hàm lấy thông tin (Sau này sẽ thay bằng gọi API)
    const getResidentInfo = (roomId) => {
        return databaseResidents[roomId] || {
            name: "--- Chưa có dữ liệu ---",
            gender: "---",
            phone: "---",
            members: 0,
            parking: "Chưa đăng ký"
        };
    };

    const info = selectedRoom ? getResidentInfo(selectedRoom) : null;

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            <div style={{ padding: '20px', color: '#fff' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý thông tin cư dân</h2>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG (Chỉ chọn 1) */}
                <div style={{ 
                    width: '210px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px',
                    border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div 
                            key={room} 
                            onClick={() => setSelectedRoom(room)}
                            style={{ 
                                background: selectedRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: selectedRoom === room ? 'white' : '#333',
                                padding: '8px 0', 
                                borderRadius: '8px', 
                                textAlign: 'center', 
                                fontSize: '11px', 
                                fontWeight: 'bold', 
                                cursor: 'pointer',
                                transition: '0.3s',
                                boxShadow: selectedRoom === room ? '0 4px 10px rgba(0,0,0,0.3)' : 'none'
                            }}
                        >
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT CƯ DÂN (Khung mờ Glassmorphism) */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: 'rgba(255,255,255,0.15)', 
                    backdropFilter: 'blur(15px)', 
                    WebkitBackdropFilter: 'blur(15px)',
                    borderRadius: '25px', 
                    border: '1px solid rgba(255,255,255,0.2)',
                    padding: '40px',
                    display: 'flex',
                    flexDirection: 'column',
                    color: '#fff',
                    boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.37)'
                }}>
                    {selectedRoom ? (
                        <div style={{ animation: 'fadeIn 0.5s' }}>
                            {/* Header chi tiết */}
                            <h1 style={{ fontSize: '50px', margin: '0 0 30px 0', borderBottom: '2px solid rgba(255,255,255,0.3)', paddingBottom: '10px' }}>
                                PHÒNG: {selectedRoom}
                            </h1>

                            {/* Bảng thông tin */}
                            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', fontSize: '18px' }}>
                                <div style={{ display: 'flex', borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: '8px' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#ddd' }}>Tên chủ phòng:</span>
                                    <span>{info.name}</span>
                                </div>
                                <div style={{ display: 'flex', borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: '8px' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#ddd' }}>Giới tính:</span>
                                    <span>{info.gender}</span>
                                </div>
                                <div style={{ display: 'flex', borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: '8px' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#ddd' }}>Liên hệ (SĐT):</span>
                                    <span>{info.phone}</span>
                                </div>
                                <div style={{ display: 'flex', borderBottom: '1px solid rgba(255,255,255,0.1)', paddingBottom: '8px' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#ddd' }}>Số lượng thành viên:</span>
                                    <span>{info.members} người</span>
                                </div>
                                <div style={{ display: 'flex' }}>
                                    <span style={{ width: '250px', fontWeight: 'bold', color: '#ddd' }}>Bãi đỗ xe:</span>
                                    <span>{info.parking}</span>
                                </div>
                            </div>

                            {/* Nút chức năng giả định */}
                            <div style={{ marginTop: '50px', display: 'flex', gap: '15px' }}>
                                <button style={{ padding: '12px 25px', borderRadius: '12px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>
                                    Cập nhật thông tin
                                </button>
                                <button style={{ padding: '12px 25px', borderRadius: '12px', border: '1px solid #fff', backgroundColor: 'transparent', color: '#fff', fontWeight: 'bold', cursor: 'pointer' }}>
                                    Lịch sử thanh toán
                                </button>
                            </div>
                        </div>
                    ) : (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', opacity: 0.6, fontSize: '20px', fontStyle: 'italic' }}>
                            Vui lòng chọn một số phòng ở danh sách bên trái để xem chi tiết thông tin cư dân...
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default QuanLyCuDan;
